// A small sprite for a bag / shop item. The files live in public/sprites/items
// and are listed in public/data/item-icons.json (generated by
// tools/download-item-sprites.cjs). Pokeballs use the shared PokeballIcon
// instead of a downloaded sprite, and items without either render nothing, so a
// newly-added item degrades gracefully until the downloader is re-run.

import { jsx } from 'react/jsx-runtime'
import { itemIcons } from '../data/gameData.js'
import { pokeBalls } from '../data/items.js'
import { isTmItem, tmMoveType } from '../data/tms.js'
import { PokeballIcon } from './pokeball-icon.js'

/** @param {{ itemId: string, size?: number, className?: string }} props */
export function ItemIcon({ itemId, size = 20, className }) {
  const file = itemIcons[itemId]
  if (file)
    return jsx('img', {
      className: `item-icon${className ? ` ${className}` : ''}`,
      src: `/sprites/items/${file}`,
      width: size,
      height: size,
      alt: '',
      draggable: false,
    })
  if (pokeBalls[itemId]) return jsx(PokeballIcon, { ballId: itemId, size })
  if (isTmItem(itemId)) {
    const type = tmMoveType(itemId)
    return jsx('span', {
      className: `tm-icon${type ? ` type-bg-${type.toLowerCase()}` : ''}${className ? ` ${className}` : ''}`,
      style: { width: size, height: size, fontSize: Math.max(6, Math.round(size * 0.42)) },
      children: 'TM',
    })
  }
  return null
}

/**
 * Whether `ItemIcon` can draw anything for an item. Callers that want a fallback
 * glyph (the minigame reward list) can check before rendering one.
 * @param {string} itemId
 * @returns {boolean}
 */
export function hasItemIcon(itemId) {
  return Boolean(itemIcons[itemId] || pokeBalls[itemId] || isTmItem(itemId))
}
